Object.assign(I18N.en,{jasperPhotoCaution:'Jasper markers show approximate BRD placements registered to the photograph. They are not exact pin or probe locations. Confirm the silkscreen and side on your own board.',jasperBottomCaution:'Only visually checked ICs and points are labelled on the underside. Other areas open TOP. A marker identifies an area, not an exact probe pad.',chooseBoardArea:'Choose a board area',jasperPositionStatus:'BRD position · photo registration',jasperBottomUnavailable:'This BOTTOM placement has not yet been checked on the photo. The related TOP area is shown, not the part itself.',jasperBottomPointHint:'is on the PCB underside. Switch to BOTTOM to see its position; the marker is not an exact probe pad.',jasperTopPointHint:'is on the PCB top and is not labelled on this BOTTOM photo.',jasperBottomOnlyIntro:'BOTTOM shows only components and points checked against the photograph. Remaining BRD placements need review.',jasperTopOnlyArea:'This area currently has labels on TOP only.',jasperBoardOnly:'Position from Jasper V1 BRD',jasperSearch:'E.g. U7D1, L8E1, J9A1',jasperExplorerIntro:'Search for a component on the selected PCB side. Unknown values remain UNKNOWN.',jasperUnpopulated:'L8D1: unpopulated footprint in the TOP photo used here. Do not measure CPUCORE there; inspect the populated L8E1 / L8F1.',footprintUnpopulated:'UNPOPULATED IN PHOTO'});
