 if(!db){stats.textContent='';note.textContent=tr('noComponentData');list.innerHTML='';pager.innerHTML='';renderComponentProfile();return}
 $('#componentExplorerTitle').textContent=state.board==='jasper'?tr('jasperExplorerTitle'):tr('componentExplorerTitle');
