 const jasper=state.board==='jasper',sideFilter=$('#componentSide'),areaFilter=$('#componentArea'),groupFilter=$('#componentGroup');
 sideFilter.hidden=areaFilter.hidden=groupFilter.hidden=!jasper;
 if(jasper){const selected=areaFilter.value,selectedGroup=groupFilter.value;areaFilter.innerHTML=`<option value="">${tr('searchAllNeighborhoods')}</option>${B.jasper.regions.map(region=>`<option value="${region.id}">${uiText(region.name)}</option>`).join('')}`;areaFilter.value=selected;groupFilter.innerHTML=`<option value="">${tr('searchAllGroups')}</option>${Object.keys(JASPER_CIRCUIT_GROUPS).map(id=>`<option value="${id}">${jasperCircuitGroupName(id)}</option>`).join('')}`;groupFilter.value=selectedGroup}
 const q=$('#componentSearch').value.trim().toLowerCase(),type=$('#componentType').value,chosenSide=jasper?sideFilter.value:state.side,area=jasper?areaFilter.value:'',group=jasper?groupFilter.value:'';
 const allSide=db.components.filter(c=>jasper?chosenSide==='all'||c.side===chosenSide:c.side===state.side);
 const sideComponents=jasper?allSide:allSide.filter(isOnPhoto);
 const filtered=sideComponents.filter(c=>componentMatchesType(c,type)&&(!group||c.schematicGroup===group)&&(!area||jasperNeighborhood(c,db)===area)&&(!q||(jasper?jasperSearchTerms(c):`${c.ref} ${c.value} ${c.device} ${c.package} ${c.function}`.toLowerCase()).includes(q)));
 const pageCount=Math.max(1,Math.ceil(filtered.length/120));state.componentPage=Math.min(state.componentPage,pageCount-1);
 const start=state.componentPage*120,visible=filtered.slice(start,start+120),withValue=sideComponents.filter(c=>c.value).length;
 stats.innerHTML=state.board==='jasper'
  ?`<strong>${sideComponents.length}/${db.components.length}</strong><span>${chosenSide==='all'?tr('searchBothSides'):chosenSide.toUpperCase()} · PCB</span><strong>${sideComponents.filter(c=>jasperPlacementState(c)==='verified').length}</strong><span>${tr('jasperPhotoConfirmed')}</span><strong>${sideComponents.filter(c=>jasperPlacementState(c)==='unverified').length}</strong><span>${tr('jasperMapApproximate')}</span><strong>${sideComponents.filter(c=>jasperPlacementState(c)==='unpopulated').length}</strong><span>${tr('jasperPhotoEmpty')}</span>`
  :`<strong>${sideComponents.length}/${allSide.length}</strong><span>${state.side==='top'?tr('topSide'):tr('bottomSide')} · PCB</span><strong>${withValue}</strong><span>${tr('sourceValue')}</span>`;
 note.textContent=filtered.length?`${tr('shown')}: ${start+1}–${start+visible.length} / ${filtered.length} · ${jasper?tr('schematicGroupingCaution'):tr('crossChecked')}`:tr('noMatches');
 list.innerHTML=visible.map(c=>{const profile=componentProfile(c.ref),status=componentStatus(c),ic=jasper?B.jasper.ics.find(item=>item[0].split(' / ').includes(c.ref)):null;return `<button class="component-row ${state.componentFocus?.ref===c.ref?'active':''}" data-component="${c.ref}"><span class="component-ref">${c.ref}<small>${jasper?c.side.toUpperCase():''}</small></span><span><b>${isUnpopulatedInPhoto(c)?tr('footprintUnpopulated'):c.value||ic?.[1]||c.device||tr('valueUnknown')}</b><small>${uiText(componentKind(c))}${jasper?` · ${jasperCircuitGroupName(c.schematicGroup)} · ${tr('schematicSheet')} ${c.schematicPage||'?'}`:''}</small></span><span class="value-badge ${componentBadgeClass(c,profile)}">${status}</span></button>`}).join('');
 pager.innerHTML=filtered.length>120?`<button data-component-page="previous" ${state.componentPage===0?'disabled':''}>← ${tr('searchPrevious')}</button><span>${tr('searchPage')} ${state.componentPage+1}/${pageCount}</span><button data-component-page="next" ${state.componentPage===pageCount-1?'disabled':''}>${tr('searchNext')} →</button>`:'';
 $$('[data-component-page]',pager).forEach(button=>button.addEventListener('click',()=>{state.componentPage+=button.dataset.componentPage==='next'?1:-1;renderComponents();list.scrollTop=0}));
 $$('[data-component]',list).forEach(b=>b.addEventListener('click',()=>focusComponent(b.dataset.component)));
 renderComponentProfile();
