function focusComponent(ref,context=null,scroll=true){
 const c=componentDb()?.components.find(x=>x.ref===ref);if(!c)return;
 const profile=componentProfile(ref);
 const placement=state.board==='jasper'?jasperPlacementState(c):'verified';
 if(state.board==='jasper'&&placement!=='verified'){
  state.selectedProfileRef=profile?.ref||ref;
  state.side=c.side;
  state.region=jasperNeighborhood(c)||'cpu';state.view=0;
  if(!regionViews(B.jasper.regions.find(item=>item.id===state.region)).length)state.region='cpu';
  updateSideUi();renderRegionMarkers();selectRegion(state.region,false);
  if(placement==='unverified'){
   state.componentFocus=c;state.fullBoardView=false;
   $('#closeupTitle').textContent=`${c.ref} · UNVERIFIED`;
   $('#zoomTabs').innerHTML=`<span class="component-focus-meta">${c.type} · ${c.package||'—'} · UNVERIFIED</span>`;
  }else showFullBoard();
  state.diagnosticContext=context||{kindKey:'componentContext',title:ref,reason:placement==='unpopulated'?jasperUnpopulatedDetail(c):placement==='outside'?{pl:I18N.pl.jasperOutsideDetail,en:I18N.en.jasperOutsideDetail}:{pl:I18N.pl.jasperUnverifiedDetail,en:I18N.en.jasperUnverifiedDetail},measure:placement==='unverified'?'UNVERIFIED':'N/A',expected:'UNKNOWN',returnTarget:'componentExplorer'};
  renderFocusedComponentDetail(c,false);renderDiagnosticContext();renderComponents();layoutPhoto();
  if(scroll)$(placement==='unverified'?'#photoViewport':'#board').scrollIntoView({block:placement==='unverified'?'center':'start'});
  return;
 }
 if(!B[state.board].images[c.side]||(state.board==='jasper'&&c.side==='bottom'&&!JASPER_BOTTOM_VERIFIED.has(c.ref))){
  const related={U8U1:['mainvrm','L8E1'],U8N1:['mainvrm','L6C1'],U4V1:['mainvrm','L6F1'],U7U2:['cpu','L8F2']}[ref]||[profile?.region||'mainvrm',null];
  state.selectedProfileRef=profile?.ref||ref;
  openBoardRegion(related[0],{kindKey:'componentContext',title:ref,reason:tr('jasperBottomUnavailable'),measure:related[1]||'UNKNOWN',expected:'UNKNOWN',returnTarget:'componentExplorer'},scroll);
  renderComponents();return;
 }
 state.side=c.side;state.componentFocus=c;state.selectedProfileRef=profile?profile.ref:ref;state.fullBoardView=false;
 state.diagnosticContext=context||(profile?profileContext(profile):{kindKey:'componentContext',title:c.ref,reason:isUnpopulatedInPhoto(c)?jasperUnpopulatedDetail(c):c.schematicPopulation==='schematic-empty'?jasperPopulationConflictDetail():c.function||c.type,measure:{pl:'Pozycja oznaczona bezpośrednio na fotografii PCB.',en:'The position is marked directly on the PCB photograph.'},expected:isUnpopulatedInPhoto(c)?'N/A':c.value||'UNKNOWN',next:isUnpopulatedInPhoto(c)?jasperUnpopulatedDetail(c):c.schematicPopulation==='schematic-empty'?jasperPopulationConflictDetail():{pl:'Obejrzyj oznaczenia i punkty w wybranym obszarze.',en:'Inspect the labels and points in the selected area.'},returnTarget:'componentExplorer'});
 state.userZoom=1;state.panX=state.panY=0;
 updateSideUi();renderRegionMarkers();renderFocusedComponentDetail(c);renderRailTrace(null,null);
 const knownIc=B[state.board].ics.find(item=>item[0]===c.ref);
  $('#closeupTitle').textContent=`${c.ref} · ${profile?bi(profile.name):knownIc?uiText(knownIc[2]):isUnpopulatedInPhoto(c)?tr('footprintUnpopulated'):c.schematicPopulation==='schematic-empty'?tr('jasperPopulationConflict'):(state.board==='jasper'&&c.side==='bottom'?JASPER_BOTTOM_FOCUS_POINTS[c.ref]:null)||c.value||c.device||tr('valueUnknown')}`;
 $('#zoomTabs').innerHTML=`<span class="component-focus-meta">${c.type} · ${c.package||'—'} · ${state.board==='jasper'?tr('jasperBoardOnly'):tr('crossChecked')}</span>`;
 renderDiagnosticContext();renderComponents();layoutPhoto();
 if(scroll)$('#photoViewport').scrollIntoView({block:'center'});
}
